// CBC mode of operation, mirroring pyaes.AESModeOfOperationCBC behavior:
// the chaining state persists across successive encrypt() calls.

import { AES } from './aes.mjs';

export class AESModeOfOperationCBC {
  // key: Uint8Array (16/24/32 bytes), iv: Uint8Array (16 bytes)
  constructor(key, iv) {
    if (iv.length !== 16) {
      throw new Error(`IV must be 16 bytes long, got ${iv.length}`);
    }
    this.aes = new AES(key);
    this.lastCipherBlock = new Uint8Array(iv);
  }

  // data: Uint8Array whose length must be a multiple of 16.
  // Returns a new Uint8Array with the ciphertext.
  encrypt(data) {
    if (data.length % 16 !== 0) {
      throw new Error('Data must be aligned to block boundary in CBC mode');
    }
    const out = new Uint8Array(data.length);
    let prev = this.lastCipherBlock;
    for (let offset = 0; offset < data.length; offset += 16) {
      const block = new Uint8Array(16);
      for (let i = 0; i < 16; i++) block[i] = data[offset + i] ^ prev[i];
      const encrypted = this.aes.encryptBlock(block);
      out.set(encrypted, offset);
      prev = encrypted;
    }
    this.lastCipherBlock = prev;
    return out;
  }
}

