// Reproduce Python's repr() of a bytes object, so that console.log output
// matches print(bytes_obj) character by character.
//
// Rules (CPython):
// - Default delimiter is a single quote; a double quote is used instead only
//   when the data contains a single quote but no double quote.
// - The delimiter and backslash are backslash-escaped.
// - \t, \n, \r use their short escapes.
// - Printable ASCII (0x20..0x7e) is emitted as-is.
// - Everything else uses \xhh with lowercase hex.

export function bytesRepr(data) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of data) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;

  let out = 'b' + String.fromCharCode(quote);
  for (const b of data) {
    if (b === quote || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += String.fromCharCode(quote);
  return out;
}

