// Minimal re-implementation of the argparse behavior used by the original
// script: four required string options (--key, --iv, --data1, --data2),
// plus -h/--help. Error output and exit codes follow Python argparse:
// usage + error message on stderr, exit code 2; help on stdout, exit code 0.

import { basename } from 'node:path';

const OPTIONS = ['key', 'iv', 'data1', 'data2'];

function progName() {
  return basename(process.argv[1] || 'test7.mjs');
}

function usageLine() {
  return `usage: ${progName()} [-h] --key KEY --iv IV --data1 DATA1 --data2 DATA2`;
}

function error(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${progName()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  let out = usageLine() + '\n\noptions:\n';
  out += '  -h, --help     show this help message and exit\n';
  for (const name of OPTIONS) {
    out += `  --${name} ${name.toUpperCase()}\n`;
  }
  process.stdout.write(out);
  process.exit(0);
}

// Parses process.argv (skipping node + script path). Returns an object
// with string values for each of key, iv, data1, data2.
export function parseArgs(argv) {
  const values = {};
  const extras = [];
  for (let i = 0; i < argv.length; i++) {
    let token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp();
    }
    let name = null;
    let value = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        value = token.slice(eq + 1);
      } else {
        name = token.slice(2);
      }
    }
    if (name !== null && OPTIONS.includes(name)) {
      if (value === null) {
        if (i + 1 >= argv.length) {
          error(`argument --${name}: expected one argument`);
        }
        value = argv[++i];
      }
      values[name] = value;
    } else {
      extras.push(token);
    }
  }
  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }
  const missing = OPTIONS.filter((name) => !(name in values));
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.map((n) => '--' + n).join(', ')}`);
  }
  return values;
}

