// Node.js (ESM) port of test7.py: AES-CBC encryption of two 16-byte blocks
// with output matching Python's print() of bytes objects.

import { AESModeOfOperationCBC } from './lib/cbc.mjs';
import { bytesRepr } from './lib/pyrepr.mjs';
import { parseArgs } from './lib/argparse.mjs';

